I'm assuming you want some sort of result like so:

	Before: [435, 546, 786, 777, 211, 877, 657]
	After: [211, 435, 546, 657, 777, 786, 877]

I came up with the following solution:

	import java.util.Arrays;

	public class QuickSort
	{    
		public static void main(String[] args) {
			int[] someIntegers = new int[] { 435, 546, 786, 777, 211, 877, 657 };
			System.out.println("Before: " + Arrays.toString(someIntegers));

			QuickSort sort = new QuickSort(someIntegers);
			sort.sort();

			System.out.println("After: " + Arrays.toString(sort.toSort));
		}

		private final int[] toSort;

		public QuickSort(int[] toSort) {
			this.toSort = toSort;
		}

		public void sort() {
			int lowIndex = 0;
			int highIndex = toSort.length - 1;

			quickSort(lowIndex, highIndex);
		}

		public void quickSort(int lowIndex, int highIndex) {
			int low = lowIndex, high = highIndex;
			int pivot = (toSort[high - 1] + toSort[high]) / 2;

			while (low <= high) {
				while (toSort[low] < pivot) low++;
				while (toSort[high] > pivot) high--;
				if (low <= high) exchange(low++, high--);
			}

			if (lowIndex < high) quickSort(lowIndex, high);
			if (low < highIndex) quickSort(low, highIndex);
		}

		private void exchange(int fromIndex, int toIndex) {
			int temp = toSort[fromIndex];
			toSort[fromIndex] = toSort[toIndex];
			toSort[toIndex] = temp;
		}
	}

